ALTER TABLE public.booking_requests ADD COLUMN owner_id uuid, ADD COLUMN service_key text, ADD COLUMN deal_value numeric(12,2), ADD COLUMN sale_closed_at timestamptz, ADD COLUMN lost_reason text;
UPDATE public.booking_requests SET service_key = CASE WHEN source = 'muutosturva-kartoitus' OR source LIKE '%muutosturva%' THEN 'muutosturva' WHEN source = '/aly' OR source LIKE 'aly-%' THEN 'aly' WHEN source LIKE '/kasvu%' THEN 'kasvu' WHEN source LIKE '/hub%' THEN 'hub' ELSE NULL END;
ALTER TABLE public.booking_requests ADD CONSTRAINT booking_deal_value_nonnegative CHECK (deal_value IS NULL OR deal_value >= 0);
CREATE TABLE public.crm_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.booking_requests(id) ON DELETE CASCADE, title text NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 200), owner_id uuid NOT NULL, due_at timestamptz NOT NULL, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.crm_tasks TO authenticated;
GRANT ALL ON public.crm_tasks TO service_role;
ALTER TABLE public.crm_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Editors manage tasks" ON public.crm_tasks FOR ALL TO authenticated USING (public.is_editor_or_admin(auth.uid())) WITH CHECK (public.is_editor_or_admin(auth.uid()));
CREATE INDEX crm_tasks_due_idx ON public.crm_tasks(due_at) WHERE completed_at IS NULL;
CREATE INDEX crm_tasks_lead_idx ON public.crm_tasks(lead_id);
CREATE TABLE public.marketing_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 150), service_key text NOT NULL, landing_path text NOT NULL CHECK (landing_path LIKE '/%' AND landing_path NOT LIKE '//%'), utm_source text NOT NULL, utm_medium text NOT NULL, utm_campaign text NOT NULL CHECK (length(trim(utm_campaign)) BETWEEN 1 AND 150), platform text CHECK (platform IN ('meta','google')), ad_campaign_id text, ad_campaign_name text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), UNIQUE (utm_source, utm_campaign));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.marketing_campaigns TO authenticated;
GRANT ALL ON public.marketing_campaigns TO service_role;
ALTER TABLE public.marketing_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Editors manage campaigns" ON public.marketing_campaigns FOR ALL TO authenticated USING (public.is_editor_or_admin(auth.uid())) WITH CHECK (public.is_editor_or_admin(auth.uid()));
CREATE TABLE public.lead_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.booking_requests(id) ON DELETE CASCADE, actor_id uuid, changes jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.lead_activity TO authenticated;
GRANT ALL ON public.lead_activity TO service_role;
ALTER TABLE public.lead_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Editors read activity" ON public.lead_activity FOR SELECT TO authenticated USING (public.is_editor_or_admin(auth.uid()));
CREATE INDEX lead_activity_lead_idx ON public.lead_activity(lead_id, created_at);
CREATE FUNCTION public.validate_crm_owner() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.owner_id IS NOT NULL AND NOT public.is_editor_or_admin(NEW.owner_id) THEN RAISE EXCEPTION 'Vastuuhenkilöllä on oltava myynnin käyttöoikeus'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_booking_owner BEFORE INSERT OR UPDATE OF owner_id ON public.booking_requests FOR EACH ROW EXECUTE FUNCTION public.validate_crm_owner();
CREATE TRIGGER validate_task_owner BEFORE INSERT OR UPDATE OF owner_id ON public.crm_tasks FOR EACH ROW EXECUTE FUNCTION public.validate_crm_owner();
CREATE FUNCTION public.audit_lead_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE diff jsonb := '{}'::jsonb; k text; BEGIN FOREACH k IN ARRAY ARRAY['status','notes','owner_id','service_key','deal_value','sale_closed_at','lost_reason'] LOOP IF to_jsonb(OLD)->k IS DISTINCT FROM to_jsonb(NEW)->k THEN diff := diff || jsonb_build_object(k, jsonb_build_object('old', to_jsonb(OLD)->k, 'new', to_jsonb(NEW)->k)); END IF; END LOOP; IF diff <> '{}'::jsonb THEN INSERT INTO public.lead_activity(lead_id, actor_id, changes) VALUES (NEW.id, auth.uid(), diff); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.audit_lead_update() FROM PUBLIC;
CREATE TRIGGER audit_booking_update AFTER UPDATE ON public.booking_requests FOR EACH ROW EXECUTE FUNCTION public.audit_lead_update();